+    // Scratch buffer for radix sort
+    std::vector<uint32_t> b(n);
+    uint32_t* current = a;
+    uint32_t* next = b.data();
+
+    // 4 passes of 8 bits each (0 to 255)
+    for (int pass = 0; pass < 4; ++pass) {
+        // Counting array (2^8 = 256 possible digits)
+        uint32_t count[256] = {0};
+        uint32_t shift = pass * 8;
+
+        // Count frequencies
+        for (size_t i = 0; i < n; ++i) {
+            uint8_t digit = (current[i] >> shift) & 0xFF;
+            count[digit]++;
+        }
+
+        // Calculate starting positions (prefix sums)
+        size_t positions[256];
+        size_t current_pos = 0;
+        for (int i = 0; i < 256; ++i) {
+            positions[i] = current_pos;
+            current_pos += count[i];
+        }
+        
+        // Scatter elements to 'next' buffer
+        for (size_t i = 0; i < n; ++i) {
+            uint8_t digit = (current[i] >> shift) & 0xFF;
+            size_t dest_idx = positions[digit]++;
+            next[dest_idx] = current[i];
+        }
+
+        // Swap roles: next becomes current, current becomes next
+        std::swap(current, next);
